"use client";

import React, { useState } from "react";

import { SpringModal } from "@/registry/open-source/spring-modal";

export default function Usage() {
	const [isOpen, setIsOpen] = useState(false);

	return (
		<div className="h-screen w-full flex items-center justify-center relative overflow-hidden bg-background">
			<div className="px-4 py-64 bg-slate-900 grid place-content-center">
				<button
					onClick={() => setIsOpen(true)}
					className="bg-gradient-to-r from-violet-600 to-indigo-600 text-secondary font-medium px-4 py-2 rounded hover:opacity-90 transition-opacity"
				>
					Open Modal
				</button>
				<SpringModal isOpen={isOpen} setIsOpen={setIsOpen} />
			</div>{" "}
		</div>
	);
}

import { Dispatch, SetStateAction, useState } from "react";

import { AnimatePresence, motion } from "motion/react";

// www.hover.dev/components/modals#spring-modal

const ExampleWrapper = () => {
	const [isOpen, setIsOpen] = useState(false);
	return (
		<div className="px-4 py-64 bg-slate-900 grid place-content-center">
			<button
				onClick={() => setIsOpen(true)}
				className="bg-gradient-to-r from-violet-600 to-indigo-600 text-foreground font-medium px-4 py-2 rounded hover:opacity-90 transition-opacity"
			>
				Open Modal
			</button>
			<SpringModal isOpen={isOpen} setIsOpen={setIsOpen} />
		</div>
	);
};

export const SpringModal = ({
	isOpen,
	setIsOpen,
}: {
	isOpen: boolean;
	setIsOpen: Dispatch<SetStateAction<boolean>>;
}) => {
	return (
		<AnimatePresence>
			{isOpen && (
				<motion.div
					initial={{ opacity: 0 }}
					animate={{ opacity: 1 }}
					exit={{ opacity: 0 }}
					onClick={() => setIsOpen(false)}
					className="bg-slate-900/20 backdrop-blur p-8 fixed inset-0 z-50 grid place-items-center overflow-y-scroll cursor-pointer"
				>
					<motion.div
						initial={{ scale: 0, rotate: "12.5deg" }}
						animate={{ scale: 1, rotate: "0deg" }}
						exit={{ scale: 0, rotate: "0deg" }}
						onClick={(e) => e.stopPropagation()}
						className="bg-gradient-to-br from-violet-600 to-indigo-600 text-foreground p-6 rounded-lg w-full max-w-lg shadow-xl cursor-default relative overflow-hidden"
					>
						<div className="relative z-10">
							<h3 className="text-3xl font-bold text-center mb-2">
								One more thing!
							</h3>
							<p className="text-center mb-6">
								Lorem ipsum dolor sit amet consectetur adipisicing elit.
								Id aperiam vitae, sapiente ducimus eveniet in velit.
							</p>
							<div className="flex gap-2">
								<button
									onClick={() => setIsOpen(false)}
									className="bg-transparent hover:bg-background/10 transition-colors text-foreground font-semibold w-full py-2 rounded"
								>
									Nah, go back
								</button>
								<button
									onClick={() => setIsOpen(false)}
									className="bg-background hover:opacity-90 transition-opacity text-indigo-600 font-semibold w-full py-2 rounded"
								>
									Understood!
								</button>
							</div>
						</div>
					</motion.div>
				</motion.div>
			)}
		</AnimatePresence>
	);
};

export default ExampleWrapper;
